<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import { ElButton } from 'element-plus'
import DiagnosticsList from '../../components/DiagnosticsList.vue'
import type { BindingChoice, ConfigImportPreview, NodeSummary, SourceView } from '../../types/domain'
const props=defineProps<{preview:ConfigImportPreview;choices:Record<string,BindingChoice>;nodes:readonly NodeSummary[];sources:readonly SourceView[];busy:boolean}>()
const emit=defineEmits<{choose:[id:string,choice:BindingChoice];confirm:[];back:[]}>()
const page=shallowRef(1),keyword=shallowRef(''),filtered=computed(()=>props.preview.nodes.filter(node=>node.originalName.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50))),visible=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
const remoteNames=computed(()=>new Map(props.nodes.map(node=>[node.id,`${node.originalName} · ${props.sources.find(source=>source.id===node.sourceId)?.name??'上游订阅'}`])))
watch(keyword,()=>{page.value=1});watch(pages,count=>{if(page.value>count)page.value=count})
function choose(id:string,value:string){emit('choose',id,{mode:value==='LOCAL'?'LOCAL':'REMOTE',remoteNodeId:value==='LOCAL'?null:value})}
</script>
<template><section class="panel" data-import-preview><header class="panel-header"><div><h2>确认导入内容</h2><p class="muted">{{ preview.nodes.length }} 个节点 · {{ preview.document.groups.length }} 个组 · {{ preview.document.rules.length }} 条规则 · {{ preview.document.providers.length }} 个规则集</p></div><span class="tag">创建独立新方案</span></header><div class="panel-body"><p class="notice">所有节点默认保留本地。仅列出参数相同的上游候选；选择关联后，该节点将随上游刷新更新。</p><DiagnosticsList :items="[...preview.report.errors,...preview.report.warnings].slice(0,100)" /><p v-if="preview.report.errors.length" class="warning">可以先创建草稿，逐项迁移不支持的内容后再发布；完整原文会单独保留。</p><div class="toolbar import-filter"><input v-model="keyword" aria-label="筛选导入节点" placeholder="筛选导入节点…"><span class="muted">{{ filtered.length }} 个匹配</span></div><div class="import-node-list scroll-area"><article v-for="node in visible" :key="node.id" class="import-node"><div><strong>{{ node.originalName }}</strong><p class="muted">{{ node.protocol }} · {{ node.suggestedRemoteId?'唯一参数匹配建议':node.candidateRemoteIds.length>1?'多个相同参数候选，请明确选择':'没有相同参数候选' }}</p></div><label>导入方式<select :value="choices[node.id]?.remoteNodeId??'LOCAL'" :aria-label="`${node.originalName} 的导入方式`" :disabled="busy" @change="event=>choose(node.id,(event.target as HTMLSelectElement).value)"><option value="LOCAL">保留本地节点</option><option v-for="id in node.candidateRemoteIds" :key="id" :value="id">关联 {{ remoteNames.get(id)??id.slice(-6) }}{{id===node.suggestedRemoteId?'（建议）':''}}</option></select></label></article></div><div v-if="pages>1" class="toolbar"><span>第 {{ page }} / {{ pages }} 页</span><div class="actions"><ElButton :disabled="page===1" @click="page--">上一页</ElButton><ElButton :disabled="page===pages" @click="page++">下一页</ElButton></div></div><div class="dialog-actions"><ElButton :disabled="busy" @click="emit('back')">返回修改 YAML</ElButton><ElButton type="primary" :loading="busy" @click="emit('confirm')">创建新方案草稿</ElButton></div></div></section></template>
<style scoped>.import-filter{margin:20px 0 10px}.import-filter input{max-width:360px}.import-node-list{max-height:55vh}.import-node{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:center;padding:18px 0;border-bottom:1px solid var(--line)}.import-node strong{overflow-wrap:anywhere}.import-node p,.import-node label{font-size:11px}.import-node p{margin-top:5px}@media(max-width:720px){.import-node{grid-template-columns:1fr}}</style>
